-- Add the new mobility progressions (straddle down into the middle split, hips and front split,
-- standing pike fold and ankle rocks) as skill workouts.
-- Generated by scripts/mobility-migration.mjs from src/skills.js; edit those, not the .sql.
-- Only new exercise ids are added. Saved workouts, XP, ranks, skill levels and baselines are unchanged.
begin;
alter function public.arc_strength_meta(text) rename to arc_strength_meta_v19;
create function public.arc_strength_meta(id text) returns jsonb
language sql immutable set search_path=public,pg_temp as $$
 select coalesce((select value from jsonb_array_elements('[{"id":"sk-pike-4","name":"Stående pikefällning","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Raka knän, fäll från höften. Låt huvudet hänga tungt. Vikten lätt fram mot tårna. Mål: 3 × 30 s med handflatorna i golvet. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"pike","skillLevel":4,"skillAnim":"standing-pike","skillSets":3,"skillAmount":30},{"id":"sk-straddle-3","name":"Hästställning","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[45,90,135,180,225,270],"cue":"Fötterna dubbelt axelbrett, tårna lätt utåt. Pressa knäna utåt över tårna. Sitt djupt med rak rygg. Mål: 3 × 45 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle","skillLevel":3,"skillAnim":"horse-stance","skillSets":3,"skillAmount":45},{"id":"sk-straddle-4","name":"Stående straddlefällning","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Fötterna brett isär, tårna framåt. Fäll från höften med lång rygg. Händerna i golvet mellan fötterna. Mål: 3 × 30 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle","skillLevel":4,"skillAnim":"straddle-fold","skillSets":3,"skillAmount":30},{"id":"sk-straddle-5","name":"Sidoglid mot spagat","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Händerna i golvet eller på block framför dig. Låt fötterna glida isär lite i taget. Spänn insidan av låren en stund, slappna sedan av och sjunk. Mål: 3 × 30 s i lägsta läget. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle","skillLevel":5,"skillAnim":"straddle-slide","skillSets":3,"skillAmount":30},{"id":"sk-straddle-6","name":"Mittspagat","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Höften i linje med fötterna. Tårna mot taket eller framåt, inte inåt. Ta dig ner via sidoglidet och ut samma väg. Mål: 3 × 30 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle","skillLevel":6,"skillAnim":"middle-split","skillSets":3,"skillAmount":30},{"id":"sk-ankles-3","name":"Fotledsgunga i djup knäböj","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"legs","pose":"skill","unit":"reps","thresholds":[10,20,30,40,50,60],"cue":"Sitt i djup knäböj. För knät fram över tårna, ett ben i taget. Hälen stannar i golvet. Mål: 2 × 10 per ben. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"ankles","skillLevel":3,"skillAnim":"squat-rocks","skillSets":2,"skillAmount":10},{"id":"sk-hips-1","name":"Höftböjarstretch i utfall","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Bakre knät i golvet, främre foten långt fram. Spänn sätet på bakre sidan. För höften framåt med rak överkropp. Mål: 3 × 30 s per sida. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"hips","skillLevel":1,"skillAnim":"hip-flexor-lunge","skillSets":3,"skillAmount":30},{"id":"sk-hips-2","name":"Duvan","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[45,90,135,180,225,270],"cue":"Främre benet böjt framför dig, bakre benet rakt bakåt. Höften rak mot golvet. Fäll långsamt framåt över främre benet. Mål: 3 × 45 s per sida. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"hips","skillLevel":2,"skillAnim":"pigeon","skillSets":3,"skillAmount":45},{"id":"sk-hips-3","name":"Couch stretch","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[45,90,135,180,225,270],"cue":"Bakre knät mot väggen, smalbenet upp längs väggen. Främre foten i golvet. Res överkroppen så långt du kan med spänt säte. Mål: 3 × 45 s per sida. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"hips","skillLevel":3,"skillAnim":"couch-stretch","skillSets":3,"skillAmount":45},{"id":"sk-hips-4","name":"Halv spagat","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Bakre knät i golvet, främre benet rakt. Tårna på främre foten mot taket. Fäll från höften med lång rygg. Mål: 3 × 30 s per sida. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"hips","skillLevel":4,"skillAnim":"half-split","skillSets":3,"skillAmount":30},{"id":"sk-hips-5","name":"Frontspagat med stöd","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Händerna på block eller golvet. Glid främre hälen fram och bakre knät bak. Höften rak framåt. Mål: 3 × 30 s per sida i lägsta läget. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"hips","skillLevel":5,"skillAnim":"split-slide","skillSets":3,"skillAmount":30},{"id":"sk-hips-6","name":"Frontspagat","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Främre benet rakt fram, bakre rakt bak. Höften rak och nära golvet. Ta dig ner via glidet och upp samma väg. Mål: 3 × 30 s per sida. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"hips","skillLevel":6,"skillAnim":"front-split","skillSets":3,"skillAmount":30}]'::jsonb) where value->>'id'=id), public.arc_strength_meta_v19(id))
$$;
revoke all on function public.arc_strength_meta_v19(text) from public,anon,authenticated;
create or replace function public.training_expansion_ready() returns integer language sql stable as $$select 20$$;
notify pgrst,'reload schema';
commit;
